// ─────────────────────────────────────────────────────────────────────────────
//  AbstractTriangle
//  Abstract triangle because it is generated by abstract geometry. THIS IS NOT A GRAPHIC OR COLLIDABLE TRIANGLE, This is used to contribute to the final geometry
// ─────────────────────────────────────────────────────────────────────────────
class AbstractTriangle {
    int vertices[3]{};
    Vector3 normal{};
    bool built = false;
    int selfIndex = -1;

    TriangleFaceType frontType = TriangleFaceType::None;
    TriangleFaceType backType  = TriangleFaceType::None;

    friend class TriangleCollection;

public:
    bool active = false;

    AbstractTriangle(int v1, int v2, int v3,
                      TriangleFaceType frontType,
                      TriangleFaceType backType = TriangleFaceType::None);

    void build();

    bool isBuilt() const { return built; }

    const int getVertex(int i) const { return vertices[i]; }

    const Vector3& getNormal() const { return normal; }

    TriangleFaceType getFrontType() const { return frontType; }
    TriangleFaceType getBackType() const { return backType; }

    void setBackType(TriangleFaceType t) { backType = t; }

    void markSuperseded() { built = true; }

    int cloneWithVertices(int v1, int v2, int v3) const;
};

#endif // SM64_PORT_ABSTRACTTRIANGLE_H